import{homeworkMarkup,mountHomeworkEditor}from './lesson-homework.js';
import{mountTeacherWork,workStateLabel}from './homework-work.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validId=value=>/^[\w-]{32}$/.test(value||'');
const cabinetHref=(mode,tab='overview',extra={})=>'#lesson?'+new URLSearchParams({view:mode,tab,...extra});
const dateLabel=lesson=>{try{return new Intl.DateTimeFormat('ru-RU',{timeZone:lesson.timeZone,day:'numeric',month:'long',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}).format(lesson.startsAt);}catch{return'Время уточняется';}};
const upcoming=(lesson,now)=>!['ended','cancelled'].includes(lesson.state)&&Number.isFinite(lesson.endsAt)&&lesson.endsAt>now;
const stateLabel=(lesson,now)=>lesson.state==='cancelled'?'Отменено':!upcoming(lesson,now)?'Завершено':lesson.state==='live'?'Занятие идёт':'Запланировано';
export function mountLearningCabinet(host,{data,tab='overview',selectedClass=null,onLesson=()=>{},onRefresh=()=>{},mountSchedule=()=>()=>{},mountHomework=()=>()=>{},mountPupils=()=>()=>{},mountTeachers=()=>()=>{},now=Date.now(),makeHref=cabinetHref}={}){
 const teacher=data?.view==='teacher';if(!['student','teacher'].includes(data?.view)||teacher&&data.canTeach!==true)throw Error('Кабинет недоступен.');
 const mode=data.view,lessons=(data.lessons||[]).filter(lesson=>validId(lesson.id)),activeLessons=lessons.filter(lesson=>upcoming(lesson,now)).sort((a,b)=>a.startsAt-b.startsAt),next=activeLessons.find(lesson=>lesson.state==='live')||activeLessons[0];
 const tasks=lessons.filter(lesson=>lesson.homework&&lesson.state!=='cancelled'),results=tasks.filter(lesson=>['accepted','needs_revision'].includes(lesson.work?.state)),pending=teacher?lessons.reduce((sum,lesson)=>sum+(Number(lesson.pendingCount)||0),0):tasks.filter(lesson=>lesson.work?.state!=='accepted').length;
 const tabs=teacher?[['overview','Обзор'],['schedule','Расписание'],['pupils','Ученики'],['homework','Домашние задания']]:[['overview','Обзор'],['lessons','Мои занятия'],['homework','Задания'],['results','Результаты']];if(teacher&&data.canManageTeachers===true)tabs.push(['teachers','Преподаватели']);if(!tabs.some(([key])=>key===tab))tab='overview';
 let stopChild=()=>{},disposed=false;
 host.innerHTML='<section class="alphabet-page learning-cabinet '+(teacher?'is-teacher':'is-student')+'"><a class="alphabet-back" href="#knowledge">← Знания</a><div class="cabinet-kicker">ОБУЧЕНИЕ · SALAH</div><h1>'+(teacher?'Кабинет преподавателя':'Моё обучение')+'</h1><p class="cabinet-welcome">'+esc(data.account?.nickname||'Участник SALAH')+'</p>'+(data.canTeach?'<nav class="cabinet-role-switch" aria-label="Кабинеты"><a href="'+makeHref('student')+'"'+(!teacher?' aria-current="page"':'')+'>Моё обучение</a><a href="'+makeHref('teacher')+'"'+(teacher?' aria-current="page"':'')+'>Преподаватель</a></nav>':'')+'<nav class="cabinet-tabs" aria-label="Разделы кабинета">'+tabs.map(([key,label])=>'<a href="'+makeHref(mode,key)+'"'+(key===tab?' aria-current="page"':'')+'>'+esc(label)+'</a>').join('')+'</nav><div class="cabinet-toolbar"><span class="cabinet-role-label">'+(teacher?'Преподаватель':'Ученик')+'</span><button type="button" class="lesson-text-button" data-refresh-cabinet>Обновить</button></div><div data-cabinet-content></div></section>';
 const root=host.querySelector('.learning-cabinet'),slot=root.querySelector('[data-cabinet-content]'),doc=root.ownerDocument;root.querySelector('[data-refresh-cabinet]').onclick=onRefresh;
 function action(container,label,run,{secondary=false,disabled=false}={}){const button=doc.createElement('button');button.type='button';button.className='button'+(secondary?' secondary':'');button.textContent=label;button.disabled=disabled;button.onclick=run;container.append(button);return button;}
 function empty(title,text){slot.innerHTML='<section class="cabinet-empty"><h2>'+esc(title)+'</h2><p>'+esc(text)+'</p></section>';}
 function lessonCard(lesson,{task=false,result=false}={}){const card=doc.createElement('article');card.className='cabinet-lesson-card';card.innerHTML='<div class="cabinet-card-top"><span class="cabinet-small-label">'+esc(task?workStateLabel(lesson.work?.state):stateLabel(lesson,now))+'</span></div><h2>'+esc(lesson.title)+'</h2><p class="cabinet-date">'+esc(dateLabel(lesson))+'</p><p class="cabinet-muted">Преподаватель: '+esc(lesson.teacherName)+'</p>'+(task?homeworkMarkup(lesson.homework):'')+(result&&lesson.work?.feedback?'<div class="cabinet-feedback"><strong>Комментарий преподавателя</strong><p dir="auto">'+esc(lesson.work.feedback)+'</p></div>':'')+(result&&lesson.work?.readingReview?'<p class="cabinet-notice">Проверка буквы: '+lesson.work.readingReview.correctCount+' из '+lesson.work.readingReview.count+' · Ошибок: '+lesson.work.readingReview.mistakeCount+'</p>':'')+'<div class="cabinet-card-actions"></div>';const controls=card.querySelector('.cabinet-card-actions');
  if(teacher){action(controls,upcoming(lesson,now)?'Управлять занятием':'Открыть расписание',()=>location.hash=makeHref('teacher','schedule',{focus:lesson.id}),{secondary:true});if(lesson.homework)action(controls,'Задание и работы',()=>location.hash=makeHref('teacher','homework',{focus:lesson.id}),{secondary:true});}
  else{if(!task&&upcoming(lesson,now)&&lesson.state==='live')action(controls,'Войти в урок',()=>onLesson(lesson.id,true));action(controls,task?(lesson.work?'Открыть свою работу':'Выполнить задание'):'Открыть занятие',()=>onLesson(lesson.id,false),{secondary:!task});}
  slot.append(card);return card;
 }
 function classPanel(kind){const available=lessons.filter(lesson=>lesson.state!=='cancelled');if(!available.length){empty('Пока нет занятий','Сначала запланируйте занятие. Затем здесь появятся ученики и домашние задания.');return;}
  const selected=available.find(lesson=>lesson.id===selectedClass)||available.find(lesson=>lesson.id===next?.id)||available[0];slot.innerHTML='<label class="cabinet-class-picker">Занятие<select aria-label="Занятие в кабинете">'+available.map(lesson=>'<option value="'+lesson.id+'"'+(lesson.id===selected.id?' selected':'')+'>'+esc(lesson.title+' · '+dateLabel(lesson))+'</option>').join('')+'</select></label><div data-class-content></div>';
  const picker=slot.querySelector('select'),content=slot.querySelector('[data-class-content]');function show(){stopChild();content.replaceChildren();const lesson=available.find(item=>item.id===picker.value);if(!lesson)return;stopChild=(kind==='pupils'?mountPupils:mountHomework)(content,lesson)||(()=>{});}picker.onchange=show;show();
 }
 if(tab==='overview'){
  slot.innerHTML='<div class="cabinet-stats"><a href="'+makeHref(mode,teacher?'schedule':'lessons')+'"><strong>'+activeLessons.length+'</strong><span>Ближайших занятий</span></a><a href="'+makeHref(mode,'homework')+'"><strong>'+pending+'</strong><span>'+(teacher?'Работ на проверке':'Заданий в работе')+'</span></a></div>';
  if(next){const hero=doc.createElement('section');hero.className='cabinet-hero';hero.innerHTML='<span class="cabinet-small-label">'+(next.state==='live'?'СЕЙЧАС ИДЁТ':'БЛИЖАЙШЕЕ ЗАНЯТИЕ')+'</span><h2>'+esc(next.title)+'</h2><p class="cabinet-date">'+esc(dateLabel(next))+'</p><p>'+esc(next.teacherName)+'</p><div class="cabinet-card-actions"></div>';const controls=hero.querySelector('.cabinet-card-actions');action(controls,teacher?'Открыть расписание':next.state==='live'?'Войти в урок':'Открыть занятие',()=>teacher?location.hash=makeHref('teacher','schedule',{focus:next.id}):onLesson(next.id,next.state==='live'));slot.append(hero);}
  else{const note=doc.createElement('section');note.className='cabinet-empty';note.innerHTML='<h2>'+(teacher?'Запланируйте новое занятие':'Ближайших занятий пока нет')+'</h2><p>'+(teacher?'Создайте урок, выберите время и поделитесь общей ссылкой с учениками.':'После записи по приглашению преподавателя здесь появится ваш урок.')+'</p>';if(teacher)action(note,'Запланировать занятие',()=>location.hash=makeHref('teacher','schedule',{new:'1'}));slot.append(note);}
  if(teacher){const shortcuts=doc.createElement('div');shortcuts.className='cabinet-shortcuts';shortcuts.innerHTML='<a href="'+makeHref('teacher','pupils')+'">Ученики занятия <span aria-hidden="true">→</span></a><a href="'+makeHref('teacher','homework')+'">Выдать и проверить ДЗ <span aria-hidden="true">→</span></a>';slot.append(shortcuts);}
  else if(tasks.length){const heading=doc.createElement('h2');heading.className='cabinet-section-title';heading.textContent='Мои задания';slot.append(heading);for(const lesson of tasks.filter(item=>item.work?.state!=='accepted').slice(0,2))lessonCard(lesson,{task:true,result:true});if(!pending){const note=doc.createElement('p');note.className='cabinet-muted';note.textContent='Все текущие задания приняты преподавателем.';slot.append(note);}}
 }else if(teacher&&tab==='teachers'&&data.canManageTeachers===true){stopChild=mountTeachers(slot)||(()=>{});}
 else if(teacher&&tab==='schedule'){stopChild=mountSchedule(slot)||(()=>{});}
 else if(teacher&&['pupils','homework'].includes(tab))classPanel(tab);
 else{const rows=tab==='homework'?tasks:tab==='results'?results:lessons.slice().sort((a,b)=>b.startsAt-a.startsAt);if(!rows.length)empty(tab==='results'?'Результатов пока нет':tab==='homework'?'Заданий пока нет':'Вы ещё не записаны на занятия',tab==='results'?'Здесь появятся комментарии и результаты проверки преподавателя.':tab==='homework'?'Преподаватель добавит домашнее задание при необходимости.':'Откройте приглашение преподавателя и запишитесь под своим аккаунтом.');else for(const lesson of rows)lessonCard(lesson,{task:tab!=='lessons',result:tab==='results'});}
 return()=>{disposed=true;stopChild();root.remove();};
}
export function mountCabinetPupils(root,{lesson,call,onReview=()=>{},isActive=()=>root.isConnected}={}){
 let disposed=false;const active=()=>!disposed&&root.isConnected&&isActive();root.innerHTML='<section class="cabinet-roster"><h2>Ученики занятия</h2><p class="cabinet-muted">'+esc(lesson.title)+'</p><p role="status">Загружаем список…</p><div data-pupils></div></section>';const status=root.querySelector('[role=status]'),list=root.querySelector('[data-pupils]');
 async function load(){try{const result=await call('class-pupils',{id:lesson.id});if(!active())return;list.replaceChildren();status.textContent=result.pupils.length?'Записаны: '+result.pupils.length:'На это занятие пока никто не записался.';for(const pupil of result.pupils){const row=root.ownerDocument.createElement('article');row.className='cabinet-pupil';row.innerHTML='<div class="cabinet-pupil-avatar" aria-hidden="true">'+esc((pupil.nickname||'У').slice(0,1).toUpperCase())+'</div><div><h3>'+esc(pupil.nickname)+'</h3><p>'+esc((pupil.workState?workStateLabel(pupil.workState):lesson.homework?'Работа ещё не отправлена':'Домашнее задание не выдано')+(pupil.readingReview?' · Ошибок: '+pupil.readingReview.mistakeCount+' из '+pupil.readingReview.count:''))+'</p></div>';if(pupil.workState){const button=root.ownerDocument.createElement('button');button.type='button';button.className='lesson-text-button';button.textContent='Проверить';button.onclick=()=>onReview(lesson.id,pupil.id);row.append(button);}list.append(row);}}catch(error){if(active()){status.textContent=error.message;const retry=root.ownerDocument.createElement('button');retry.type='button';retry.className='button secondary';retry.textContent='Повторить';retry.onclick=()=>{retry.remove();void load();};list.replaceChildren(retry);}}}void load();return()=>{disposed=true;root.replaceChildren();};
}
export function mountCabinetHomework(root,{lesson,call,isActive=()=>root.isConnected,selectedStudent=null}={}){
 let current=lesson,disposed=false,stop=()=>{};const active=()=>!disposed&&root.isConnected&&isActive();root.innerHTML='<section class="cabinet-homework"><nav class="cabinet-inline-tabs" aria-label="Домашнее задание"><button type="button" data-task>Задание</button><button type="button" data-works>Работы учеников</button></nav><div data-content></div></section>';const slot=root.querySelector('[data-content]'),task=root.querySelector('[data-task]'),works=root.querySelector('[data-works]');
 function select(work){stop();slot.replaceChildren();task.setAttribute('aria-pressed',String(!work));works.setAttribute('aria-pressed',String(work));if(work)stop=mountTeacherWork(slot,{lesson:current,call,isActive:active,studentId:selectedStudent});else stop=mountHomeworkEditor(slot,{lesson:current,onCancel:()=>show(),onSave:async(homework,expectedHomeworkRevision)=>{const result=await call('set-homework',{id:current.id,homework,expectedHomeworkRevision});if(!active())return;current=result.lesson;stop();show('ДЗ сохранено.');}});}
 function show(message=''){slot.innerHTML=(message?'<p class="cabinet-notice" role="status">'+esc(message)+'</p>':'')+homeworkMarkup(current.homework)+'<button class="button secondary" type="button" data-edit>'+(current.homework?'Изменить задание':'Добавить задание')+'</button>';slot.querySelector('[data-edit]').onclick=()=>select(false);}
 task.onclick=()=>select(false);works.onclick=()=>select(true);select(Boolean(selectedStudent)||Boolean(current.homework));return()=>{disposed=true;stop();root.replaceChildren();};
}
